entries[172405] = { ["name"] = "Tome of Hex: Living Honey", ["text"] = "Binds when picked up\nClasses: Shaman\nUse: Teaches Hex: Living Honey.\nTransforms the enemy into a living honey for 1 min. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.\nSell Price:" }
