entries[172905] = { ["name"] = "Flexible Ectoplasmic Specs", ["text"] = "Binds when picked up\nHead Cloth\n12 Armor\n+18 Intellect\n+27 Stamina\n+ 18 Random Stat 1\n+ 18 Random Stat 2\nDurability 85 / 85\nEquip: Increases your Shadowlands Engineering by 20.\nUse: Allows you to look far into the distance.\nRequires Shadowlands Engineering (1)\nSell Price:" }
