entries[172910] = { ["name"] = "Darkmoon Card of Repose", ["text"] = "\"A random Darkmoon Card from the Repose suit. Collect a full set to receive a reward.\"" }
entries[172912] = { ["name"] = "Momentum Redistributor Boots", ["text"] = "Binds when used\nUse: Redistributes a significant portion of damage you would take from your next fall into nearby enemies. Lasts 10 sec.\n\nCannot be used in instances. (5 Min Cooldown)\nRequires Shadowlands Engineering (1)\n\"Allows you to do a super heroic landing!\"\nSell Price:" }
entries[172914] = { ["name"] = "Gravimetric Scrambler Cannon", ["text"] = "Binds when used\nUse: Destabilizes gravity around a target location, hindering nearby enemies' movement for 10 sec, launching them in random directions, or throwing them up in the air.\n\nUnless it backfires.\nRequires Shadowlands Engineering (1)\n\"Sometimes called a \"Black Hole Gun\", which is inaccurate. It's really more of an artillery piece.\"\nSell Price:" }
entries[172915] = { ["name"] = "50UL-TR4P", ["text"] = "Binds when used\nUse: Place a containment device on the ground that, once armed, will activate when an enemy steps on it, banishing them for 1 min.\n\nUnless it backfires.\n\nReduced effect against players. (3 Min Cooldown)\nRequires Shadowlands Engineering (1)\n\"Who will you be in communications with?!\"\nSell Price:" }
entries[172917] = { ["name"] = "Belt Modification: Dimensional Shifter", ["text"] = "Use: Permanently attaches a specialized device to your belt, allowing you to fear an enemy within melee range for 5 sec.\n\nOnly the engineer's belt can be modified, and doing so will cause them to become soulbound.\n\"You are unable to assail that which you are incapable of visually perceiving!\"" }
entries[172918] = { ["name"] = "Belt Modification: Electro-Jump", ["text"] = "Use: Permanently attaches a specialized device to your belt, allowing you to fear an enemy within melee range for 5 sec.\n\nOnly the engineer's belt can be modified, and doing so will cause them to become soulbound.\n\"Ride the lightning!\"" }
entries[172919] = { ["name"] = "Belt Modification: Damage Retaliator", ["text"] = "Use: Permanently attaches a specialized device to your belt, allowing you to fear an enemy within melee range for 5 sec.\n\nOnly the engineer's belt can be modified, and doing so will cause them to become soulbound.\n\"I am comprised of highly elastic bands, you consist entirely of liquid adhesive...\"" }
entries[172920] = { ["name"] = "Optical Target Embiggener", ["text"] = "Use: Permanently attaches a scope to a ranged weapon, causing it to occasionally increase Critical Strike by 824 for 12 sec when dealing damage with ranged attacks.\n\nAttaching this device to a ranged weapon causes it to become soulbound.\n\"Boom. Headshot.\"\nSell Price:" }
entries[172921] = { ["name"] = "Infra-green Reflex Sight", ["text"] = "Use: Permanently attaches a scope to a ranged weapon, causing it to occasionally increase Haste by 824 for 12 sec when dealing damage with ranged attacks.\n\nAttaching this device to a ranged weapon causes it to become soulbound.\n\"No one can hide from my sight.\"\nSell Price:" }
entries[172923] = { ["name"] = "Precision Lifeforce Inverter", ["text"] = "Binds when equipped\nRanged Gun\n13 - 25 Damage Speed 3.00\n(6.3 damage per second)\n+9 Agility\n+13 Stamina\n+ 9 Random Stat 1\n+ 9 Random Stat 2\nDurability 85 / 85\n\"Extremely effective at making enemy combatants less healthy.\"\nSell Price:" }
entries[172924] = { ["name"] = "Wormhole Generator: Shadowlands", ["text"] = "Binds when used\nToy\nUse: Open a wormhole that allows the user to quickly travel to one of several fixed points within the Shadowlands. (15 Min Cooldown)\nRequires Shadowlands Engineering (1)\n\"CAUTION: Failure to operate within strict safety guidelines may result in... double death? Turbo death? Aliveness?\"\nSell Price:" }
entries[172925] = { ["name"] = "Faceless Mask of the Burned Bridge", ["text"] = "Binds when picked up\nUse: When moving, spawn void zones behind you that drain Sanity.\n\"Nothing left but the faint smell of smoke and a memory of eyes watering.\"" }
entries[172926] = { ["name"] = "Necrostatic Micro Capacitor", ["text"] = "Optional Crafting Reagent\n\nProvides the following property: Completing World Quests increase Primary Stat\n\"An Optional Reagent that, when crafted into a piece of armor, increases the wearer's Primary Stat for completing World Quests.\"\nSell Price:" }
