entries[173280] = { ["name"] = "Token of Death's Door", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Breath of the Dying.\nMajor Power:\nReaping Flames\n40 yd range Instant 45 sec cooldown Burn your target with a bolt of Azerite, dealing 3067 Fire damage. If the target has less than 20% health , the cooldown is reduced by 30 sec.\nMinor Power:\nLethal Strikes\n40 yd range\nApproximately 10 procs per minute Your spells and abilities have a chance to strike your target for 1244 Fire damage .\n\nUnique: Corruption Resistance increased by 10." }
entries[173281] = { ["name"] = "Token of Death's Mark", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Breath of the Dying.\nMajor Power:\nReaping Flames\n40 yd range Instant 45 sec cooldown Burn your target with a bolt of Azerite, dealing 3067 Fire damage. If the target has less than 20% health or more than 80% health, the cooldown is reduced by 30 sec.\nMinor Power:\nLethal Strikes\n40 yd range\nApproximately 10 procs per minute Your spells and abilities have a chance to strike your target for 1244 Fire damage, and heal you for 50% of the damage dealt.\n\nUnique: Corruption Resistance increased by 10." }
entries[173282] = { ["name"] = "Token of Death's Glee", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Breath of the Dying.\nLearn any Rank 3 Rajani or Uldum Accord essence on another character to unlock this essence.\nRequires you to be Revered with the Uldum Accord. (Cannot purchase if already known.)\nMajor Power:\nReaping Flames\n40 yd range Instant 45 sec cooldown Burn your target with a bolt of Azerite, dealing 3067 Fire damage. If the target has less than 20% health or more than 80% health, the cooldown is reduced by 30 sec.\n\nIf Reaping Flames kills an enemy, its cooldown is lowered to 5 sec and it will deal 100% increased damage on its next use.\nMinor Power:\nLethal Strikes\n40 yd range\nApproximately 10 procs per minute Your spells and abilities have a chance to strike your target for 1244 Fire damage, and heal you for 50% of the damage dealt.\n\nIf your target is below 20% health, the chance for extra damage is increased by 400%.\n\nUnique: Corruption Resistance increased by 10.\n\"A whisper of things to come.\"" }
entries[173283] = { ["name"] = "Token of a Brilliant Death", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Breath of the Dying.\nMajor Power:\nReaping Flames\n40 yd range Instant 45 sec cooldown Burn your target with a bolt of Azerite, dealing 3067 Fire damage. If the target has less than 20% health or more than 80% health, the cooldown is reduced by 30 sec.\n\nIf Reaping Flames kills an enemy, its cooldown is lowered to 5 sec and it will deal 100% increased damage on its next use.\nMinor Power:\nLethal Strikes\n40 yd range\nApproximately 10 procs per minute Your spells and abilities have a chance to strike your target for 1244 Fire damage, and heal you for 50% of the damage dealt.\n\nIf your target is below 20% health, the chance for extra damage is increased by 400%.\n\nUnique: Corruption Resistance increased by 10." }
