entries[173288] = { ["name"] = "Overflowing Azerite Geode", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Spark of Inspiration.\nMajor Power:\nMoment of Glory\n40 yd range 1.5 sec cast 1 min cooldown Release a wave of energy from your Heart of Azeroth, increasing the damage all party members within 15 yds deal with Azerite Essences by 45% for the next 10 sec.\nMinor Power:\nUnified Strength\n40 yd range\nApproximately 3 procs per minute Your spells and abilities have a chance to increase [you and 2 other allies'][your] Haste by 30 for 8 sec and reduce the cooldown of [you and 2 other allies'][your] currently slotted Major Essence by 1.0 sec.\n\nUnique: Corruption Resistance increased by 10." }
entries[173289] = { ["name"] = "Pulsing Azerite Geode", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Spark of Inspiration.\nMajor Power:\nMoment of Glory\n40 yd range 1.5 sec cast 1 min cooldown Release a wave of energy from your Heart of Azeroth, increasing the damage all party members within 15 yds deal with Azerite Essences by 45% for the next 20 sec.\nMinor Power:\nUnified Strength\n40 yd range\nApproximately 4 procs per minute Your spells and abilities have a chance to increase you and 1 other ally's Haste by 30 for 8 sec and reduce the cooldown of you and 1 other ally's currently slotted Major Essence by 1.0 sec.\n\nUnique: Corruption Resistance increased by 10." }
entries[173290] = { ["name"] = "Quickening Azerite Geode", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Spark of Inspiration.\nLearn any Rank 3 essence from Horrific Visions on another character to unlock this essence.\nMajor Power:\nMoment of Glory\n40 yd range 1.5 sec cast 1 min cooldown Release a wave of energy from your Heart of Azeroth, increasing the damage all party members within 15 yds deal with Azerite Essences by 45% and their Speed by 64 for the next 20 sec.\nMinor Power:\nUnified Strength\n40 yd range\nApproximately 4 procs per minute Your spells and abilities have a chance to increase you and 2 other allies' Haste by 30 for 8 sec and reduce the cooldown of you and 2 other allies' currently slotted Major Essence by 1.0 sec.\n\nUnique: Corruption Resistance increased by 10." }
entries[173291] = { ["name"] = "Luminous Azerite Geode", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Spark of Inspiration.\nMajor Power:\nMoment of Glory\n40 yd range 1.5 sec cast 1 min cooldown Release a wave of energy from your Heart of Azeroth, increasing the damage all party members within 15 yds deal with Azerite Essences by 45% and their Speed by 64 for the next 20 sec.\nMinor Power:\nUnified Strength\n40 yd range\nApproximately 4 procs per minute Your spells and abilities have a chance to increase you and 2 other allies' Haste by 30 for 8 sec and reduce the cooldown of you and 2 other allies' currently slotted Major Essence by 1.0 sec.\n\nUnique: Corruption Resistance increased by 10." }
